/** SINH TỰ ĐỘNG bởi scratchpad/agt/lab/ch5/tao-ma.mjs (2026-11-24) — mã lab + output THẬT (Node 22.22.2 máy nhà + node:22-alpine 22.23.5 trong container, git 2.55.0). Đừng sửa tay. */
export const MA = {
 "chayReadme": "// chay-readme.mjs — \"README có chạy được trên máy mới không?\": lấy mọi khối ```bash trong README,\n// chạy lần lượt trong một container node:22-alpine SẠCH (không mạng, chỉ có tệp đã commit), dừng ở khối hỏng đầu tiên.\n// Khối có dòng <!-- nen --> ngay trước: chạy nền (như \"mở terminal riêng để nó chạy\"), chờ 2 giây rồi in log.\n// Dùng: node chay-readme.mjs <thư-mục-repo> <README.md>\nimport { execFileSync, spawnSync } from 'node:child_process';\nimport fs from 'node:fs';\n\nconst [repo, readme] = process.argv.slice(2);\nconst TEN = 'agt-readme';\nconst dk = (...a) => spawnSync('docker', a, { encoding: 'utf8' });\n\n// 1. Tách khối lệnh, nhớ số dòng để báo lỗi chỉ đúng chỗ trong README.\nconst dong = fs.readFileSync(readme, 'utf8').split('\\n');\nconst khoi = [];\nfor (let i = 0; i < dong.length; i++) {\n  if (dong[i].trim() !== '```bash') continue;\n  const bd = i + 1, than = [];\n  while (dong[++i].trim() !== '```') than.push(dong[i]);\n  khoi.push({ dong: bd, lenh: than.join('\\n'), nen: dong[bd - 2]?.trim() === '<!-- nen -->' });\n}\nconsole.log(`${readme.split('/').pop()}: ${khoi.length} khối lệnh bash`);\n\n// 2. \"Máy mới\": container sạch, chỉ chép các tệp mà git sẽ đưa cho người clone (.env bị .gitignore loại).\ndk('rm', '-f', TEN);\nconst c = dk('run', '-d', '--name', TEN, '--network', 'none', '--memory', '2g', '--memory-swap', '2g', '--cpus', '2',\n  'node:22-alpine', 'sleep', '300');\nif (c.status) { console.error(c.stderr); process.exit(2); }\nconst tam = fs.mkdtempSync('/tmp/agt-readme-');\nexecFileSync('sh', ['-c', `cd \"${repo}\" && git init -q . 2>/dev/null; git add -A && git -c user.name=x -c user.email=x@x commit -qm tam >/dev/null; git archive HEAD | tar -x -C \"${tam}\"; rm -rf .git`]);\nfs.copyFileSync(readme, `${tam}/README.md`);\ndk('cp', `${tam}/.`, `${TEN}:/lam`);\nfs.rmSync(tam, { recursive: true });\n\n// 3. Chạy từng khối.\nlet n = 0, hong = false;\nfor (const k of khoi) {\n  n++;\n  console.log(`\\n[khối ${n} · dòng ${k.dong}${k.nen ? ' · chạy nền' : ''}] ${k.lenh.replaceAll('\\n', ' ⏎ ')}`);\n  const t0 = Date.now();\n  let r;\n  if (k.nen) {\n    dk('exec', '-d', '-w', '/lam', TEN, 'sh', '-c', `${k.lenh} > /tmp/nen.log 2>&1`);\n    spawnSync('sleep', ['2']);\n    r = dk('exec', TEN, 'sh', '-c', 'cat /tmp/nen.log; pgrep -f \"node --env-file\" >/dev/null');\n  } else r = dk('exec', '-w', '/lam', TEN, 'sh', '-ec', k.lenh);\n  const ra = (r.stdout + r.stderr).trim().split('\\n').filter(Boolean);\n  const xem = ra.length > 14 ? [...ra.slice(0, 7), `… (bỏ ${ra.length - 13} dòng)`, ...ra.slice(-6)] : ra;\n  for (const l of xem) console.log('  ' + l);\n  if (r.status === 0) console.log(`  ✓ exit 0 (${((Date.now() - t0) / 1000).toFixed(1)} s)`);\n  else { console.log(`  ✗ exit ${r.status} — người mới kẹt ở dòng ${k.dong} của README.`); hong = true; break; }\n}\ndk('rm', '-f', TEN);\nconsole.log(hong ? `\\nKẾT QUẢ: README HỎNG ở khối ${n}/${khoi.length}.` : `\\nKẾT QUẢ: chạy hết ${khoi.length}/${khoi.length} khối trên máy sạch.`);\nprocess.exit(hong ? 1 : 0);",
 "readmeV1": "# LabFlow\n\nĐồ án SWP391 nhóm 3 — hệ thống đặt lịch phòng lab.\n\n## Cài đặt\n\n```bash\nnpm install\n```\n\n## Chạy\n\n```bash\nnpm run dev\n```\n\nMở http://localhost:3000 là xong.\n\n## Thành viên\n\n- An (leader), Bình, Chi, Dũng, Em",
 "readmeV2": "# LabFlow — đặt lịch phòng lab và mượn thiết bị\n\nĐồ án SWP391 (SP27), nhóm 3. React + Spring Boot + PostgreSQL. Trạng thái: iteration 2 đang chạy.\nTệp này dành cho người mới vào repo: làm đúng từ trên xuống, **mỗi bước có dòng \"Đúng khi\"** để biết mình chưa lạc.\nPhần dưới là phía FE; phía BE có `be/README.md` cùng cấu trúc.\n\n## 1. Cần có trên máy\n\n| Công cụ | Phiên bản | Kiểm bằng |\n|---|---|---|\n| Node.js | ≥ 22 (nhóm dùng 22 LTS) | `node --version` |\n| Git | ≥ 2.40 | `git --version` |\n\n```bash\nnode --version\n```\n\nĐúng khi: in ra `v22.` hoặc cao hơn. Thấp hơn ⇒ cài Node 22 LTS trước, đừng đi tiếp.\n\n## 2. Chạy lần đầu (khoảng 10 phút)\n\nChép tệp cấu hình mẫu (`.env` không được commit — mỗi máy một bản):\n\n```bash\ncp .env.example .env\nnpm install\nnpm run kiem-moi-truong\n```\n\nĐúng khi: mọi dòng bắt đầu bằng ✓. Dòng ✗ nói rõ thiếu gì.\n\n```bash\nnpm test\n```\n\nĐúng khi: dòng `# fail 0`.\n\nMở một terminal riêng và để nó chạy:\n\n<!-- nen -->\n```bash\nnpm start\n```\n\nĐúng khi: in `LabFlow FE chạy ở http://localhost:45173`. Kiểm từ terminal khác (hoặc mở địa chỉ đó trong trình duyệt):\n\n```bash\nnode -e \"fetch('http://localhost:45173/suc-khoe').then(r => r.text()).then(console.log)\"\n```\n\nĐúng khi: `{\"ok\":true,\"api\":\"http://localhost:45180\"}`.\n\n## 3. Tài khoản mẫu (chỉ có ở CSDL dev)\n\n| Vai | Đăng nhập | Mật khẩu |\n|---|---|---|\n| Sinh viên | sv01@labflow.test | xem `be/db/seed/README.md` |\n| Quản lý lab | ql01@labflow.test | như trên |\n\n## 4. Màn hình nào ở đâu, ai phụ trách\n\nBảng này SINH từ `docs/phan-cong.csv` bằng `node scripts/ban-do.mjs` — đừng sửa tay; CI chạy `--kiem` để chặn README lỗi thời.\n\n<!-- ban-do:bat-dau -->\n<!-- ban-do:ket-thuc -->\n\n## 5. Đóng góp\n\nNhánh `feat/LF-<số>-<mô-tả>`, commit theo Conventional Commits, PR nhỏ ≤ 400 dòng, một người duyệt theo lịch xoay vòng — chi tiết ở `CONTRIBUTING.md`. Quyết định lớn của nhóm ở `docs/adr/`.\n\n## 6. Kẹt ở đâu\n\n| Thấy | Nghĩa là | Làm |\n|---|---|---|\n| `node: .env: not found` | chưa chép `.env` | quay lại bước 2 |\n| `EADDRINUSE` | cổng 45173 đang bận | đổi `PORT` trong `.env` |\n| `Thiếu biến môi trường API_URL` | `.env` cũ, thiếu khoá mới | so với `.env.example` |\n\nVẫn kẹt sau 30 phút ⇒ hỏi ở kênh #labflow-dev, dán nguyên văn lỗi + lệnh đã gõ.",
 "banDo": "// ban-do.mjs — sinh bảng \"màn hình → thư mục → người phụ trách\" trong README từ docs/phan-cong.csv (nguồn sự thật duy nhất).\n//   node scripts/ban-do.mjs          ghi bảng vào README.md (giữa hai dấu ban-do)\n//   node scripts/ban-do.mjs --kiem   không ghi; exit 1 nếu README lệch CSV (dùng trong CI)\nimport fs from 'node:fs';\nconst [dau, ...hang] = fs.readFileSync('docs/phan-cong.csv', 'utf8').trim().split('\\n').map((d) => d.split(','));\nconst c = Object.fromEntries(dau.map((k, i) => [k, i]));\nconst ds = hang.sort((a, b) => a[c.it] - b[c.it] || a[c.man].localeCompare(b[c.man], 'en', { numeric: true }));\nconst bang = ['| Màn | Tên | Thư mục | Phụ trách | Iteration | Ticket |', '|---|---|---|---|---|---|',\n  ...ds.map((h) => `| ${h[c.man]} | ${h[c.ten]} | \\`fe/src/modules/${h[c.mien]}/\\` | ${h[c.chu]} | ${h[c.it]} | ${h[c.ticket]} |`)].join('\\n');\nconst README = fs.readFileSync('README.md', 'utf8');\nconst moi = README.replace(/(<!-- ban-do:bat-dau -->\\n)[\\s\\S]*?(<!-- ban-do:ket-thuc -->)/, `$1${bang}\\n$2`);\nif (!process.argv.includes('--kiem')) { fs.writeFileSync('README.md', moi); console.log(`Đã ghi ${ds.length} màn vào README.md`); }\nelse if (moi === README) console.log(`✓ README khớp docs/phan-cong.csv (${ds.length} màn)`);\nelse {\n  const cu = new Set(README.split('\\n')), lech = moi.split('\\n').filter((d) => !cu.has(d));\n  console.log(`✗ README lỗi thời so với docs/phan-cong.csv — ${lech.length} dòng phải đổi:`);\n  for (const d of lech) console.log('  + ' + d);\n  console.log('  Sửa: node scripts/ban-do.mjs && git add README.md');\n  process.exit(1);\n}",
 "kiemMoiTruong": "// Kiểm máy trước khi chạy: phiên bản Node, tệp .env, đủ khoá như .env.example.\nimport fs from 'node:fs';\nlet loi = 0;\nconst ok = (dk, msg) => { console.log(`${dk ? '✓' : '✗'} ${msg}`); if (!dk) loi++; };\nconst major = Number(process.versions.node.split('.')[0]);\nok(major >= 22, `Node ${process.versions.node} (cần ≥ 22)`);\nconst can = fs.readFileSync('.env.example', 'utf8').match(/^[A-Z_]+(?==)/gm);\nconst co = fs.existsSync('.env') ? fs.readFileSync('.env', 'utf8').match(/^[A-Z_]+(?==)/gm) ?? [] : null;\nok(co !== null, '.env tồn tại');\nif (co) for (const k of can) ok(co.includes(k), `.env có ${k}`);\nprocess.exit(loi ? 1 : 0);",
 "pkg": "{\n  \"name\": \"labflow-fe\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"engines\": { \"node\": \">=22\" },\n  \"scripts\": {\n    \"start\": \"node --env-file=.env src/server.mjs\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"kiem-moi-truong\": \"node scripts/kiem-moi-truong.mjs\"\n  }\n}",
 "envMau": "# Chép thành .env rồi sửa nếu cần. KHÔNG commit .env (đã có trong .gitignore).\nPORT=45173\nAPI_URL=http://localhost:45180",
 "adr": "// adr.mjs — sổ quyết định kiến trúc (ADR, mẫu Michael Nygard 2011) của nhóm, mỗi quyết định một tệp docs/adr/NNNN-<slug>.md.\n//   node scripts/adr.mjs moi \"<tiêu đề>\" [--thay N]   tạo ADR mới (Đề xuất); --thay N: ADR mới thay ADR N, sửa trạng thái cả hai\n//   node scripts/adr.mjs chap-nhan N                  đổi trạng thái ADR N thành Chấp nhận\n//   node scripts/adr.mjs ds                           in mục lục và ghi docs/adr/README.md\n//   node scripts/adr.mjs kiem                         soát cả sổ (dùng trong CI): exit 1 nếu có lỗi\nimport fs from 'node:fs';\nconst D = 'docs/adr', NGAY = process.env.ADR_NGAY ?? new Date().toISOString().slice(0, 10);\nconst so4 = (n) => String(n).padStart(4, '0');\nconst slug = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 50).replace(/^-|-$/g, '');\nconst tep = () => (fs.existsSync(D) ? fs.readdirSync(D).filter((f) => /^\\d{4}-.*\\.md$/.test(f)).sort() : []);\nconst doc = (f) => fs.readFileSync(`${D}/${f}`, 'utf8');\nconst timTep = (n) => tep().find((f) => f.startsWith(so4(n) + '-'));\nconst tieuDe = (s) => s.match(/^# \\d+\\. (.*)$/m)?.[1] ?? '?';\nconst trangThai = (s) => s.match(/^- Trạng thái: (.*)$/m)?.[1] ?? '?';\nconst datTrangThai = (f, tt) => fs.writeFileSync(`${D}/${f}`, doc(f).replace(/^- Trạng thái: .*$/m, `- Trạng thái: ${tt}`));\nconst [lenh, ...thamSo] = process.argv.slice(2);\n\nif (lenh === 'moi') {\n  const td = thamSo[0], thay = thamSo.includes('--thay') ? Number(thamSo[thamSo.indexOf('--thay') + 1]) : null;\n  const n = Math.max(0, ...tep().map((f) => Number(f.slice(0, 4)))) + 1, f = `${so4(n)}-${slug(td)}.md`;\n  const cu = thay && timTep(thay);\n  if (thay && !cu) { console.error(`Không có ADR ${so4(thay)}`); process.exit(1); }\n  fs.mkdirSync(D, { recursive: true });\n  fs.writeFileSync(`${D}/${f}`, `# ${n}. ${td}\\n\\n- Trạng thái: Đề xuất\\n- Ngày: ${NGAY}\\n${cu ? `- Thay cho: [${so4(thay)}](${cu})\\n` : ''}\n## Bối cảnh\\n\\nTODO: lực tác động nào (kỹ thuật, lịch, con người) khiến phải quyết? Chỉ nêu sự thật.\\n\n## Quyết định\\n\\nTODO: \"Chúng ta sẽ …\" — câu đầy đủ, chủ động.\\n\n## Hệ quả\\n\\n- (+) TODO\\n- (−) TODO: cái giá phải trả — luôn có.\\n`);\n  if (cu) datTrangThai(cu, `Bị thay bởi [${so4(n)}](${f})`);\n  console.log(`Đã tạo ${D}/${f}${cu ? ` (thay ${cu})` : ''}`);\n} else if (lenh === 'chap-nhan') {\n  const f = timTep(Number(thamSo[0]));\n  datTrangThai(f, 'Chấp nhận'); console.log(`${f}: Chấp nhận`);\n} else if (lenh === 'ds') {\n  const dong = tep().map((f) => `| [${f.slice(0, 4)}](${f}) | ${tieuDe(doc(f))} | ${trangThai(doc(f)).replace(/\\]\\(/, '](')} |`);\n  const md = `# Sổ quyết định kiến trúc (ADR) — LabFlow\\n\\nSINH bởi \\`node scripts/adr.mjs ds\\`. Mẫu: Bối cảnh · Quyết định · Hệ quả (Nygard 2011).\\n\\n| Số | Quyết định | Trạng thái |\\n|---|---|---|\\n${dong.join('\\n')}\\n`;\n  fs.writeFileSync(`${D}/README.md`, md);\n  for (const f of tep()) console.log(`${f.slice(0, 4)}  ${trangThai(doc(f)).replace(/\\[(\\d+)\\]\\([^)]*\\)/, '$1').padEnd(16)} ${tieuDe(doc(f))}`);\n} else if (lenh === 'kiem') {\n  let loi = 0;\n  const bao = (f, m) => { console.log(`✗ ${f}: ${m}`); loi++; };\n  const theoSo = {};\n  for (const f of tep()) (theoSo[f.slice(0, 4)] ??= []).push(f);\n  for (const [s, ds] of Object.entries(theoSo)) if (ds.length > 1) bao(ds.join(' + '), `trùng số ${s} (hai nhánh cùng tạo ADR mới?)`);\n  for (const f of tep()) {\n    const s = doc(f), muc = {};\n    for (const m of s.split(/^## /m).slice(1)) muc[m.split('\\n')[0].trim()] = m.split('\\n').slice(1).join('\\n').trim();\n    for (const k of ['Bối cảnh', 'Quyết định', 'Hệ quả']) if (!muc[k] || /TODO/.test(muc[k])) bao(f, `mục \"${k}\" trống hoặc còn TODO`);\n    const tt = trangThai(s);\n    if (!/^(Đề xuất|Chấp nhận|Bị bác|Lỗi thời|Bị thay bởi \\[\\d{4}\\]\\(.+\\))$/.test(tt)) bao(f, `trạng thái lạ: \"${tt}\"`);\n    if (muc['Quyết định'] && !/(Chúng ta|Nhóm) sẽ/.test(muc['Quyết định'])) bao(f, 'Quyết định không có câu \"Chúng ta sẽ …\" — chưa rõ đã chọn gì');\n    if (muc['Hệ quả'] && !/^- \\(−\\)/m.test(muc['Hệ quả'])) bao(f, 'Hệ quả chỉ có mặt tốt — ghi cả cái giá (−)');\n    const moi = tt.match(/\\((\\d{4}-[^)]+)\\)/)?.[1];\n    if (moi && (!fs.existsSync(`${D}/${moi}`) || !doc(moi).includes(`(${f})`))) bao(f, `bị thay bởi ${moi} nhưng tệp đó không trỏ ngược \"Thay cho\"`);\n  }\n  console.log(loi ? `KẾT QUẢ: ${loi} lỗi trong ${tep().length} ADR` : `✓ ${tep().length} ADR hợp lệ`);\n  process.exit(loi ? 1 : 0);\n} else console.log('Dùng: adr.mjs moi \"<tiêu đề>\" [--thay N] | chap-nhan N | ds | kiem');",
 "adr2": "## Bối cảnh\n\nSWP391 chấm LOC và phần trình bày theo màn hình của từng người. Chia \"2 người FE, 2 người BE, 1 người test\" khiến người làm BE không có màn nào đứng tên, người FE phải chờ API, và không ai giải thích trọn một luồng khi giảng viên hỏi.\n\n## Quyết định\n\nChúng ta sẽ giao mỗi người trọn một số màn hình theo lát dọc: giao diện React, API Spring Boot, bảng và migration của màn đó. Phần dùng chung (layout, đăng nhập, phân quyền) có một chủ là C1 và vào repo trước bằng PR khung.\n\n## Hệ quả\n\n- (+) LOC và trách nhiệm rõ theo người; demo theo màn.\n- (+) Không ai chờ người khác làm xong nửa kia.\n- (−) Ai cũng phải viết cả React lẫn Spring — tuần 1 làm cặp đôi để người yếu phía nào học phía đó.\n- (−) Mã chung thành điểm nóng; mọi PR chạm `fe/src/routes.js` cần chủ tệp duyệt (CODEOWNERS).",
 "adr7": "## Bối cảnh\n\nĐêm 23/02/2027 PR mang V3 merge sau khi staging đã ở V4; Flyway từ chối, staging đứng gần 12 giờ mà không ai biết (postmortem `docs/postmortem/2027-02-24-staging-migration.md`). ADR 0003 dựa vào mắt người review để bắt trùng số — đã không bắt được.\n\n## Quyết định\n\nChúng ta sẽ giữ cách đánh số tuần tự nhưng cho máy kiểm: CI chạy `ci/kiem-migration.mjs` trên mọi PR, chặn migration có số không lớn hơn mọi số trên main. CI đỏ vì số cũ thì tác giả rebase và đổi số. Không bật `outOfOrder` ở staging.\n\n## Hệ quả\n\n- (+) Lỗi trùng hoặc ngược thứ tự bị chặn trước khi merge, không phụ thuộc người review.\n- (−) PR mở lâu có thể phải đổi số nhiều lần.",
 "adrXau": "## Bối cảnh\n\nDùng Redis cho nhanh.\n\n## Quyết định\n\nRedis.\n\n## Hệ quả\n\n- (+) Nhanh hơn nhiều.",
 "adr9": "## Bối cảnh\n\nADR 0005 squash mọi PR. Ở PR #41 (S35, C5 và C3 cùng làm), squash gộp 14 commit thành một; dòng Co-authored-by có, nhưng `git blame` chỉ còn tên C5 và không tách được phần của từng người khi giảng viên hỏi.\n\n## Quyết định\n\nChúng ta sẽ squash PR do một người làm, và dùng merge commit cho PR có từ hai tác giả trở lên; trước khi merge, tác giả dọn commit trong nhánh còn 2–5 commit có nghĩa.\n\n## Hệ quả\n\n- (+) Lịch sử giữ đúng ai làm phần nào ở PR làm chung.\n- (−) Hai kiểu merge — người merge phải nhìn số tác giả; ghi vào mẫu PR.",
 "maTran": "// ma-tran.mjs — bài 5.3: so phương án cho RFC-001 (trợ lý AI của LabFlow) bằng ma trận có trọng số,\n// rồi làm điều ma trận hay bị bỏ qua: (1) lọc ràng buộc cứng TRƯỚC khi chấm điểm, (2) thử độ nhạy của từng trọng số,\n// (3) đo thật kích thước dữ liệu mỗi phương án phải gửi ra ngoài.\nconst TIEU_CHI = [ // [tên, trọng số 0–5]\n  ['Trả lời đúng', 5], ['Dữ liệu cá nhân ở lại trong trường', 5], ['Công sức (ít = điểm cao)', 3],\n  ['Chi phí mỗi tháng', 2], ['Độ trễ', 2], ['Ấn tượng khi demo', 3],\n];\nconst PA = { // điểm 1–5 theo đúng thứ tự TIEU_CHI; lý do từng điểm ghi trong RFC\n  'A — gửi câu hỏi + cả lịch tuần cho LLM': { diem: [3, 1, 4, 2, 2, 5], coAI: true },\n  'B — LLM chỉ đổi câu hỏi thành truy vấn JSON': { diem: [5, 4, 2, 4, 3, 4], coAI: true },\n  'C — không LLM: ô tìm + mẫu câu cố định': { diem: [5, 5, 4, 5, 5, 1], coAI: false },\n};\nconst tong = (d, w) => d.reduce((s, x, i) => s + x * w[i], 0);\nconst W = TIEU_CHI.map((t) => t[1]);\nconst xep = (ds, w) => ds.map((p) => [p, tong(PA[p].diem, w)]).sort((a, b) => b[1] - a[1]);\n\nconsole.log('1) Chấm cả ba, trọng số như bảng:');\nfor (const [p, s] of xep(Object.keys(PA), W)) console.log(`   ${String(s).padStart(3)}  ${p}`);\nconsole.log('\\n2) Ràng buộc cứng của đề tài \"LabFlow AI\": phải có tính năng AI ⇒ loại trước khi chấm:');\nconst conLai = Object.keys(PA).filter((p) => PA[p].coAI);\nfor (const p of Object.keys(PA)) if (!PA[p].coAI) console.log(`   loại: ${p}`);\nconst thang = xep(conLai, W)[0][0];\nfor (const [p, s] of xep(conLai, W)) console.log(`   ${String(s).padStart(3)}  ${p}`);\n\nconsole.log(`\\n3) Độ nhạy: đổi MỘT trọng số từ 0 tới 10 (các trọng số khác giữ nguyên) — ${thang.slice(0, 1)} còn thắng không?`);\nfor (let i = 0; i < W.length; i++) {\n  const lat = [];\n  for (let w = 0; w <= 10; w++) {\n    const w2 = [...W]; w2[i] = w;\n    const t = xep(conLai, w2)[0][0];\n    if (t !== thang) lat.push(`${w}→${t.slice(0, 1)}`);\n  }\n  console.log(`   ${TIEU_CHI[i][0].padEnd(36)} (đang ${W[i]}): ${lat.length ? 'LẬT khi ' + lat.slice(0, 3).join(', ') + (lat.length > 3 ? ' …' : '') : 'không lật'}`);\n}\n\n// 3b) Cùng trọng số, nhưng người thích A chấm A lạc quan (không có số đo): \"LLM giỏi lắm, đúng 5\"; \"chỉ là lịch thôi, dữ liệu 3\".\nconst lacQuan = 'A — gửi câu hỏi + cả lịch tuần cho LLM';\nconst goc = PA[lacQuan].diem; PA[lacQuan].diem = [5, 3, 4, 2, 2, 5];\nconsole.log(`\\n3b) Giữ trọng số, chỉ đổi điểm A thành [${PA[lacQuan].diem}] (chấm theo cảm tính):`);\nfor (const [p, s] of xep(conLai, W)) console.log(`   ${String(s).padStart(3)}  ${p}`);\nfor (let i = 0; i < W.length; i++) {\n  const lat = [];\n  for (let w = 0; w <= 10; w++) { const w2 = [...W]; w2[i] = w; const t = xep(conLai, w2)[0][0]; lat.push(t.slice(0, 1)); }\n  console.log(`   ${TIEU_CHI[i][0].padEnd(36)} w=0…10: ${lat.join('')}`);\n}\nPA[lacQuan].diem = goc;\n\n// 4) Đo thật: dữ liệu mỗi lời gọi gửi cho LLM. Lịch tuần giả lập tất định: 14 lab × 6 ngày × 6 ca, ~70 % kín.\nlet hat = 7; const rnd = () => ((hat = (hat * 1103515245 + 12345) % 2 ** 31) / 2 ** 31);\nconst lich = [];\nfor (let lab = 1; lab <= 14; lab++) for (let ngay = 1; ngay <= 6; ngay++) for (let ca = 1; ca <= 6; ca++)\n  if (rnd() < 0.7) lich.push({ lab: `AL-${300 + lab}`, ngay, ca, sv: `SE18${String(Math.floor(rnd() * 9000) + 1000)}`, ten: 'Nguyễn Văn …', ghiChu: 'đồ án nhóm' });\nconst hoi = 'Thứ Sáu ca 3 lab nào còn trống?';\nconst goiA = JSON.stringify({ he_thong: 'Bạn là trợ lý đặt lab. Dữ liệu lịch tuần:', lich, hoi });\nconst goiB = JSON.stringify({ he_thong: 'Đổi câu hỏi thành JSON {ngay, ca, loai}. Chỉ trả JSON.', hoi });\nconst mssv = new Set(lich.map((x) => x.sv)).size;\nconsole.log(`\\n4) Đo kích thước một lời gọi (lịch tuần giả lập: ${lich.length} lượt đặt):`);\nconsole.log(`   A: ${goiA.length.toLocaleString('vi-VN')} ký tự, chứa ${mssv} MSSV khác nhau`);\nconsole.log(`   B: ${goiB.length.toLocaleString('vi-VN')} ký tự, chứa 0 MSSV (chỉ câu hỏi)`);\nconsole.log(`   A gấp B ${(goiA.length / goiB.length).toFixed(0)} lần mỗi câu hỏi.`);",
 "anDanh": "// an-danh.mjs — bài 5.3: phương án B vẫn gửi CÂU HỎI của người dùng ra LLM ngoài. Câu hỏi có thể chứa dữ liệu cá nhân.\n// Thử hai lớp che trước khi gửi: (1) chỉ regex, (2) regex + danh bạ tên lấy từ bảng nguoi_dung. Đếm cái còn lọt.\nconst CAU = [\n  'Mình là Nguyễn Thị Hoa SE180123, thứ Sáu ca 3 lab AI-302 còn chỗ không?',\n  'Đặt giúp em lab AL-305 sáng mai, có gì gọi 0912 345 678 hoặc hoa.nt@fpt.edu.vn',\n  'Lịch của bạn Trần Minh Khang tuần này thế nào?',\n  'cho hỏi khang ơi máy chiếu phòng 304 hỏng chưa sửa à',\n  'Lab AL-310 có cắm hoa trang trí cho buổi bảo vệ không?',\n];\nconst DANH_BA = ['Nguyễn Thị Hoa', 'Trần Minh Khang']; // lấy từ bảng nguoi_dung (họ tên đầy đủ)\nconst LUAT = [\n  ['MSSV', /\\b(SE|HE|HS|DE|QE|CE|SS)\\d{6}\\b/gi],\n  ['EMAIL', /[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+/g],\n  ['SĐT', /\\b0\\d{2,3}[ .]?\\d{3}[ .]?\\d{3,4}\\b/g],\n];\nconst che = (s, danhBa) => {\n  const gap = [];\n  for (const [nhan, re] of LUAT) s = s.replace(re, (m) => (gap.push(`${nhan}:${m}`), `[${nhan}]`));\n  for (const ten of danhBa) {\n    // tên đầy đủ, rồi tên gọi (từ cuối) đứng riêng — không phân biệt hoa thường\n    const goi = ten.split(' ').at(-1);\n    for (const re of [new RegExp(ten, 'gi'), new RegExp(`(?<![\\\\p{L}])${goi}(?![\\\\p{L}])`, 'giu')])\n      s = s.replace(re, (m) => (gap.push(`TÊN:${m}`), '[TÊN]'));\n  }\n  return [s, gap];\n};\nfor (const [nhanLop, danhBa] of [['Lớp 1 — chỉ regex', []], ['Lớp 2 — regex + danh bạ tên từ CSDL', DANH_BA]]) {\n  console.log(`== ${nhanLop}`);\n  for (const c of CAU) {\n    const [ra, gap] = che(c, danhBa);\n    console.log(`  vào: ${c}\\n  ra : ${ra}\\n       che ${gap.length}: ${gap.join(', ') || '—'}`);\n  }\n}",
 "rfcV1": "# RFC-001: Chatbot AI\n\nDùng ChatGPT API làm chatbot cho LabFlow. Backend lấy lịch cả tuần gửi kèm câu hỏi cho GPT, GPT trả lời lab nào trống.\nEm làm màn S40, khoảng 3 ngày. Mọi người góp ý nhé.",
 "rfcV2": "# RFC-001: Trợ lý AI trả lời \"lab nào còn trống\"\n\n- Tác giả: C2 · Trạng thái: Đang góp ý · Hạn góp ý: 03/03/2027 (thứ Tư) · Người duyệt: cả nhóm, gửi GV hướng dẫn đọc trước\n- Màn: S40 (iteration 3) · Ticket: LF-60\n\n## Bối cảnh và phạm vi\n\nĐề tài là \"LabFlow AI\": hội đồng sẽ hỏi phần AI làm gì. Khảo sát nhanh 23 bạn trong lớp: câu hỏi hay gặp nhất là \"thứ X ca Y lab nào trống\", \"lab nào có máy chiếu\". Hiện phải mở S20 (tìm phòng trống) và chọn 3 bộ lọc.\n\n## Mục tiêu\n\n- Gõ một câu tiếng Việt tự nhiên, nhận danh sách lab trống ĐÚNG với dữ liệu thật trong CSDL.\n- Trả lời dưới 3 giây cho 90 % câu hỏi.\n\n## Không làm\n\n- Không cho AI đặt lịch thay người dùng (chỉ trả kết quả + nút sang S22).\n- Không trả lời câu hỏi về người khác (\"lịch của bạn X\") — đi qua quyền như mọi API khác.\n- Không tự huấn luyện mô hình.\n\n## Phương án\n\n### A — Gửi câu hỏi + cả lịch tuần cho LLM, LLM tự trả lời\n- Đánh đổi: làm nhanh nhất, demo ấn tượng; nhưng mỗi câu gửi ~32 nghìn ký tự chứa 348 MSSV ra máy chủ ngoài (đo bằng `ma-tran.mjs`), và LLM có thể \"bịa\" một lab trống.\n\n### B — LLM chỉ đổi câu hỏi thành truy vấn JSON, backend tra CSDL\n- Đánh đổi: kết quả luôn từ CSDL thật, chỉ câu hỏi (đã che) đi ra ngoài; nhưng phải viết bộ kiểm JSON và xử lý khi LLM trả sai định dạng — thêm khoảng 2 ngày.\n\n### C — Không dùng LLM: ô tìm kiếm + mẫu câu cố định\n- Đánh đổi: rẻ, nhanh, đúng; nhưng không đáp ứng yêu cầu \"AI\" của đề tài.\n\n## So sánh\n\nMa trận trọng số và thử độ nhạy: `node ma-tran.mjs` (kết quả dán ở PR). C loại vì ràng buộc đề tài; B 77 điểm, A 55; B không lật khi đổi riêng bất kỳ trọng số nào trong 0–10.\n\n## Đề xuất\n\nChọn B. A chỉ thắng khi chấm theo cảm tính (đúng 5, dữ liệu 3) — chưa có số đo nào ủng hộ.\n\n## Dữ liệu cá nhân và an ninh\n\n- Chỉ câu hỏi đi ra ngoài, sau khi che MSSV, email, SĐT và tên có trong bảng `nguoi_dung` (`an-danh.mjs`). Che bằng regex không đủ: lọt tên, và che nhầm \"hoa\" — ghi vào rủi ro.\n- Khoá API ở biến môi trường máy chủ, không ở FE.\n- JSON từ LLM được kiểm bằng schema; trường lạ ⇒ từ chối, không ghép vào SQL.\n\n## Triển khai và rút lui\n\nCờ tính năng `AI_TRO_LY=off` mặc định. Bật ở staging tuần 10, chạy 20 câu hỏi mẫu, đạt ≥ 18/20 mới bật cho demo. Lỗi hoặc hết hạn mức API ⇒ tự quay về form S20.\n\n## Câu hỏi mở\n\n| Câu hỏi | Ai trả lời | Hạn |\n|---|---|---|\n| Trường có cho gửi dữ liệu câu hỏi của SV ra dịch vụ ngoài không? | C1 hỏi GV | 26/02/2027 |\n| Dùng nhà cung cấp LLM nào, hạn mức miễn phí bao nhiêu? | C2 | 01/03/2027 |",
 "rfc002": "# RFC-002: Nhắc lịch trước 1 giờ\n\n- Tác giả: C4 · Trạng thái: Đang góp ý · Hạn góp ý: 10/03/2027\n- Màn: không có màn mới · Ticket: LF-62\n\n## Bối cảnh và phạm vi\n\nTuần 8 có 11/52 lượt đặt lab bỏ trống (không đến, không huỷ). Quản lý lab đề nghị nhắc sinh viên trước giờ vào lab.\n\n## Mục tiêu\n\n- Giảm lượt bỏ trống xuống dưới 5 % trong 2 tuần thử.\n\n## Không làm\n\n- Không gửi SMS (tốn tiền, cần số điện thoại).\n\n## Phương án\n\n### A — Email qua SMTP của Gmail nhóm, cron mỗi 5 phút\n- Đánh đổi: miễn phí, làm trong 1 ngày; nhưng Gmail giới hạn số thư/ngày và dễ vào thư rác.\n\n### B — Thông báo trong ứng dụng (chuông ở góc màn hình)\n- Chỉ thấy khi đang mở LabFlow.\n\n## Đề xuất\n\nChọn A, B làm sau.\n\n## Câu hỏi mở\n\n| Câu hỏi | Ai trả lời | Hạn |\n|---|---|---|\n| Có được dùng email @fpt.edu.vn của sinh viên không? | C1 hỏi GV | 05/03/2027 |\n| Giờ nhắc 1 giờ hay 30 phút? | quản lý lab | |",
 "kiemRfc": "// kiem-rfc.mjs — soát hình thức một RFC/tài liệu thiết kế trước khi xin góp ý. Máy chỉ bắt thiếu sót hình thức;\n// nội dung (bối cảnh đúng chưa, điểm chấm có bằng chứng chưa) vẫn là việc của người đọc.\nimport fs from 'node:fs';\nconst s = fs.readFileSync(process.argv[2], 'utf8');\nconst muc = {};\nfor (const m of s.split(/^## /m).slice(1)) muc[m.split('\\n')[0].trim()] = m.split('\\n').slice(1).join('\\n').trim();\nconst loi = [], bao = (m) => loi.push(m);\nfor (const k of ['Bối cảnh và phạm vi', 'Mục tiêu', 'Không làm', 'Phương án', 'Đề xuất', 'Câu hỏi mở']) if (!muc[k]) bao(`thiếu mục \"${k}\"`);\nconst pa = (muc['Phương án'] ?? '').split(/^### /m).slice(1);\nif (muc['Phương án'] && pa.length < 2) bao(`chỉ có ${pa.length} phương án — cần ít nhất 2 để có gì mà chọn`);\nfor (const p of pa) if (!/Đánh đổi:/.test(p)) bao(`phương án \"${p.split('\\n')[0]}\" không nêu đánh đổi`);\nif (/\\b(AI|LLM|GPT|API ngoài|ChatGPT)\\b/.test(s) && !muc['Dữ liệu cá nhân và an ninh']) bao('gửi dữ liệu ra dịch vụ ngoài nhưng không có mục \"Dữ liệu cá nhân và an ninh\"');\nfor (const d of (muc['Câu hỏi mở'] ?? '').split('\\n').filter((d) => /^\\|/.test(d) && !/^\\|[-| ]+\\|$/.test(d)).slice(1))\n  if (!/\\| *C\\d.*\\| *\\d{2}\\/\\d{2}\\/\\d{4} *\\|$/.test(d)) bao(`câu hỏi mở thiếu người trả lời hoặc hạn: ${d}`);\nif (!/Hạn góp ý: \\d{2}\\/\\d{2}\\/\\d{4}/.test(s)) bao('không có \"Hạn góp ý: dd/mm/yyyy\" — góp ý sẽ kéo dài mãi');\nconsole.log(loi.length ? loi.map((m) => '✗ ' + m).join('\\n') + `\\nKẾT QUẢ: ${loi.length} lỗi — chưa gửi đi góp ý` : `✓ ${process.argv[2].split('/').pop()}: đủ mục, ${pa.length} phương án có đánh đổi, câu hỏi mở có người + hạn`);\nprocess.exit(loi.length ? 1 : 0);",
 "ciLog": "2027-02-22T10:06:40+07:00 deploy-staging #112 OK   flyway: áp 1 migration, CSDL đang ở phiên bản 4\n2027-02-23T21:41:12+07:00 deploy-staging #118 FAIL flyway LỖI: Validate failed: Detected resolved migration not applied to database: 3.\n2027-02-23T21:41:13+07:00 deploy-staging #118 NOTIFY email → c1@nhom.example (chủ repo)\n2027-02-24T09:31:05+07:00 deploy-staging #119 OK   flyway: áp 1 migration, CSDL đang ở phiên bản 4\n2027-02-24T10:36:50+07:00 deploy-staging #120 OK   flyway: áp 0 migration, CSDL đang ở phiên bản 4",
 "chat": "[24/02/2027 09:10] C2: staging bấm Đặt lịch ra lỗi 500 \"relation dat_lich does not exist\", có ai biết không? 13:00 review với cô rồi\n[24/02/2027 09:14] C1: CI deploy đỏ từ 21:41 tối qua. Mail báo về hòm thư của mình, tối qua mình không mở\n[24/02/2027 09:16] C1: V3 của PR #29 merge sau V4 của PR #34, staging đã ở V4 nên Flyway từ chối V3\n[24/02/2027 09:25] C1: tạm bật FLYWAY_OUT_OF_ORDER ở staging để kịp review, sẽ tắt sau\n[24/02/2027 09:40] C2: staging Đặt lịch chạy lại rồi, cảm ơn\n[24/02/2027 10:28] C4: revert #34 vì bảng ngày nghỉ lệch múi giờ, làm lại sau\n[24/02/2027 13:00] C1: review iteration 2 xong, cô hỏi vì sao sáng nay staging đỏ\n[24/02/2027 16:05] C3: sao staging vẫn có bảng ngay_nghi dù #34 đã revert?",
 "dongThoiGian": "// dong-thoi-gian.mjs — dựng dòng thời gian sự cố từ BA nguồn có giờ thật: git log, log CI, nhóm chat (xuất văn bản).\n// Ghép, xếp theo giờ, tính các mốc: bắt đầu (CI FAIL đầu tiên) · phát hiện (người đầu tiên nói về lỗi) · giảm nhẹ (CI OK đầu tiên sau đó).\n// Dùng: node dong-thoi-gian.mjs <repo> <ci.log> <chat.txt> [từ-ngày]\nimport { execFileSync } from 'node:child_process';\nimport fs from 'node:fs';\nconst [repo, ciLog, chat, tu = '2027-02-22T00:00'] = process.argv.slice(2);\nconst sk = [];\nfor (const d of execFileSync('git', ['-C', repo, 'log', '--all', `--since=${tu}`, '--format=%aI|%an|%s'], { encoding: 'utf8' }).trim().split('\\n'))\n  { const [gio, ai, ...s] = d.split('|'); sk.push({ t: new Date(gio), nguon: 'git', ai: ai.replace('Dev ', ''), noi: s.join('|') }); }\nfor (const d of fs.readFileSync(ciLog, 'utf8').trim().split('\\n'))\n  { const [gio, ...s] = d.split(' '); sk.push({ t: new Date(gio), nguon: 'CI', ai: '—', noi: s.join(' ').replace(/\\s+/g, ' ') }); }\nfor (const d of fs.readFileSync(chat, 'utf8').trim().split('\\n')) {\n  const m = d.match(/^\\[(\\d\\d)\\/(\\d\\d)\\/(\\d{4}) (\\d\\d:\\d\\d)\\] (\\w+): (.*)$/);\n  sk.push({ t: new Date(`${m[3]}-${m[2]}-${m[1]}T${m[4]}:00+07:00`), nguon: 'chat', ai: m[5], noi: m[6] });\n}\nsk.sort((a, b) => a.t - b.t);\nconst gio = (t) => t.toLocaleString('vi-VN', { timeZone: 'Asia/Saigon', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });\nlet truoc = null;\nfor (const e of sk) {\n  if (truoc && e.t - truoc > 6 * 3600e3) console.log(`   ⋯ ${((e.t - truoc) / 3600e3).toFixed(1)} giờ không có sự kiện nào ⋯`);\n  console.log(`${gio(e.t)}  ${e.nguon.padEnd(4)} ${e.ai.padEnd(3)} ${e.noi.length > 92 ? e.noi.slice(0, 91) + '…' : e.noi}`);\n  truoc = e.t;\n}\nconst batDau = sk.find((e) => e.nguon === 'CI' && / FAIL /.test(e.noi));\nconst phatHien = sk.find((e) => e.nguon === 'chat' && e.t > batDau.t && /lỗi|hỏng|đỏ|500/.test(e.noi));\nconst giam = sk.find((e) => e.nguon === 'CI' && e.t > batDau.t && / OK /.test(e.noi));\nconst p = (a, b) => { const m = Math.round((b - a) / 60e3); return `${Math.floor(m / 60)} giờ ${m % 60} phút`; };\nconsole.log(`\\nBắt đầu  : ${gio(batDau.t)} (${batDau.noi.slice(0, 40)}…)`);\nconsole.log(`Phát hiện: ${gio(phatHien.t)} (${phatHien.ai}) — sau ${p(batDau.t, phatHien.t)}`);\nconsole.log(`Giảm nhẹ : ${gio(giam.t)} — ${p(phatHien.t, giam.t)} sau khi phát hiện; staging hỏng tổng ${p(batDau.t, giam.t)}`);",
 "pmV1": "# Báo cáo sự cố staging 24/02\n\n## Chuyện gì xảy ra\n\nTối 23/02 C1 merge PR #29 mà không kiểm tra nên staging chết cả đêm. C1 cũng không đọc mail CI. C3 cũng có lỗi vì merge V4 trước mà không báo ai.\n\n## Nguyên nhân\n\nDo C1 cẩu thả khi merge.\n\n## Hành động\n\n| Việc | Chủ | Hạn |\n|---|---|---|\n| Mọi người cẩn thận hơn khi merge | cả nhóm | |\n| C1 rút kinh nghiệm, tối phải đọc mail | C1 | |",
 "pmV2": "# Postmortem: staging từ chối migration V3, hỏng 11 giờ 50 phút (23–24/02/2027)\n\n- Viết: C1 (điều phối) · Họp rà soát: 24/02/2027 16:30, đủ 5 người · Trạng thái: hành động đang làm\n- Không đổ lỗi: mỗi người đã làm điều hợp lý với thông tin họ có lúc đó. Ta sửa hệ thống, không sửa người.\n\n## Tóm tắt\n\nPR #29 (bảng `dat_lich`, migration V3, mở từ 15/02) merge lúc 21:40 ngày 23/02, sau PR #34 (V4) đã chạy trên staging. Flyway từ chối V3; bản deploy lỗi, staging giữ bản cũ thiếu bảng `dat_lich`. Cảnh báo duy nhất là một email; sáng 24/02 mới có người thấy. Khắc phục tạm bằng `outOfOrder` lúc 09:31, kịp buổi review 13:00.\n\n## Ảnh hưởng\n\n- Staging hỏng chức năng Đặt lịch 11 giờ 50 phút (21:41 → 09:31).\n- 2 người mất khoảng 1 giờ chuẩn bị review; giảng viên hỏi về sự cố trong buổi review.\n- Không mất dữ liệu (staging chỉ có dữ liệu mẫu).\n\n## Dòng thời gian\n\nSinh bằng `node dong-thoi-gian.mjs` từ git log, log CI và nhóm chat — xem phụ lục. Mốc chính: bắt đầu 21:41 (23/02) · phát hiện 09:10 (24/02, sau 11 giờ 29 phút) · giảm nhẹ 09:31.\n\n## Nguyên nhân gốc và yếu tố góp phần\n\n5 lần \"vì sao\":\n1. Vì sao staging hỏng? Flyway từ chối V3 vì CSDL đã ở V4.\n2. Vì sao V3 tới sau V4? Nhánh LF-21 sống 8 ngày; số migration lấy lúc tạo nhánh, không lấy lúc merge.\n3. Vì sao không bị chặn trước khi merge? Quy ước (ADR 0003) dựa vào người review nhìn số; CI không kiểm thứ tự migration.\n4. Vì sao 11 giờ mới phát hiện? Cảnh báo chỉ là email tới hòm thư chủ repo; nhóm làm việc trên kênh chat, không ai trực staging.\n5. Vì sao bản sửa tạm lại tạo rủi ro mới? `outOfOrder` + revert #34 để lại bảng `ngay_nghi` trên staging mà repo không còn — staging lệch với mã (C3 phát hiện 16:05).\n\n## Điều làm tốt\n\n- Phát hiện xong, 21 phút đã có bản tạm; tin nhắn ở kênh chung ghi rõ nguyên nhân.\n- Revert #34 đúng cách (git revert, không sửa lịch sử).\n\n## Hành động\n\n| Việc | Loại | Chủ | Hạn | Ticket |\n|---|---|---|---|---|\n| CI chạy `kiem-migration.mjs`, chặn số migration không lớn hơn main (ADR 0007) | ngăn | C1 | 26/02/2027 | LF-70 |\n| Cảnh báo deploy đỏ gửi vào kênh chat nhóm, gắn tên người merge | phát hiện | C4 | 26/02/2027 | LF-71 |\n| Tắt `outOfOrder`, dựng lại CSDL staging từ migration trên main | giảm nhẹ | C3 | 25/02/2027 | LF-72 |\n| Thêm vào DoD: \"đã xem staging sau khi merge\" | ngăn | C2 | 01/03/2027 | LF-73 |\n\n## Phụ lục\n\nOutput đầy đủ của `dong-thoi-gian.mjs`; lab 3.3 (chạy Flyway thật) dựng lại được sự cố.",
 "soatPm": "// soat-postmortem.mjs — soát một postmortem trước buổi rà soát: đủ mục, không câu nào quy lỗi cho một người,\n// hành động cụ thể (có chủ, hạn, ticket, không dùng động từ \"cố gắng\"), có cả hành động NGĂN lẫn PHÁT HIỆN.\nimport fs from 'node:fs';\nconst s = fs.readFileSync(process.argv[2], 'utf8'), loi = [], bao = (m) => loi.push(m);\nconst muc = {};\nfor (const m of s.split(/^## /m).slice(1)) muc[m.split('\\n')[0].trim()] = m.split('\\n').slice(1).join('\\n').trim();\nfor (const k of ['Tóm tắt', 'Ảnh hưởng', 'Dòng thời gian', 'Hành động']) if (!muc[k]) bao(`thiếu mục \"${k}\"`);\nif (!Object.keys(muc).some((k) => /^Nguyên nhân/.test(k))) bao('thiếu mục nguyên nhân');\nconst NGUOI = /\\b(C[1-5]|An|Bình|Chi|Dũng|Em)\\b/u, QUY_LOI = /(cẩu thả|lỗi của|có lỗi|không chịu|ẩu|vô trách nhiệm|lười|đáng lẽ|tại (anh|chị|bạn|em)|mà không kiểm tra)/iu;\nfor (const cau of s.replace(/^\\|.*$/gm, '').split(/(?<=[.!?])\\s+|\\n/)) if (NGUOI.test(cau) && QUY_LOI.test(cau)) bao(`câu quy lỗi cho người: \"${cau.trim()}\"`);\nconst hang = (muc['Hành động'] ?? '').split('\\n').filter((d) => /^\\|/.test(d) && !/^\\|[-| ]+\\|$/.test(d));\nconst cot = (hang[0] ?? '').split('|').map((x) => x.trim()), i = (k) => cot.indexOf(k);\nfor (const k of ['Chủ', 'Hạn', 'Ticket', 'Loại']) if (i(k) < 0) bao(`bảng hành động thiếu cột \"${k}\"`);\nfor (const d of hang.slice(1)) {\n  const o = d.split('|').map((x) => x.trim());\n  if (/(cẩn thận|chú ý|rút kinh nghiệm|cố gắng|nhắc nhở|nghiêm túc)/i.test(o[1])) bao(`hành động không kiểm được: \"${o[1]}\"`);\n  if (i('Chủ') >= 0 && !/^C[1-5]$/.test(o[i('Chủ')])) bao(`\"${o[1]}\": chủ phải là MỘT người (đang: \"${o[i('Chủ')]}\")`);\n  if (i('Hạn') >= 0 && !/^\\d{2}\\/\\d{2}\\/\\d{4}$/.test(o[i('Hạn')])) bao(`\"${o[1]}\": thiếu hạn`);\n}\nconst loai = hang.slice(1).map((d) => d.split('|')[i('Loại')]?.trim());\nif (i('Loại') >= 0) for (const l of ['ngăn', 'phát hiện']) if (!loai.includes(l)) bao(`không có hành động loại \"${l}\"`);\nconsole.log(loi.length ? loi.map((m) => '✗ ' + m).join('\\n') + `\\nKẾT QUẢ: ${loi.length} lỗi` : `✓ ${process.argv[2].split('/').pop()}: đủ mục, không quy lỗi, ${hang.length - 1} hành động có chủ + hạn + ticket (${[...new Set(loai)].join(', ')})`);\nprocess.exit(loi.length ? 1 : 0);",
 "kiemTaiLieu": "#!/bin/bash\n# kiem-tai-lieu.sh — bước CI \"tài liệu\": chạy mọi bộ soát, in đủ lỗi của từng bộ, exit 1 nếu có bộ nào đỏ.\n# Không thay người đọc: máy bắt thiếu mục, lỗi thời, trùng số, quy lỗi, hành động mơ hồ; nội dung đúng hay sai vẫn cần review.\ncd \"$(dirname \"$0\")/..\"; do_=0\nbuoc() { local ten=$1; shift; local ra; ra=$(\"$@\" 2>&1); local e=$?; [ $e = 0 ] && echo \"✓ $ten\" || { echo \"✗ $ten\"; echo \"$ra\" | grep -v '^✓' | sed 's/^/    /'; do_=1; }; }\nbuoc \"README khớp phân công\"  node scripts/ban-do.mjs --kiem\nbuoc \"Sổ ADR\"                 node scripts/adr.mjs kiem\nfor f in docs/rfc/*.md;        do buoc \"RFC $(basename $f)\"        node scripts/kiem-rfc.mjs $f; done\nfor f in docs/postmortem/*.md; do buoc \"Postmortem $(basename $f)\" node scripts/soat-postmortem.mjs $f; done\n[ $do_ = 0 ] && echo \"TÀI LIỆU: XANH\" || echo \"TÀI LIỆU: ĐỎ — sửa rồi push lại\"\nexit $do_",
 "ngoaiThuTu": "### Thứ Hai: PR ngày nghỉ (V4) merge trước, staging tự migrate:\n$ ls mig; flyway migrate (staging)\nV1__tai_khoan.sql V2__lab_thiet_bi.sql V4__ngay_nghi.sql \nflyway: áp 3 migration, CSDL đang ở phiên bản 4\n(exit 0)\n### Thứ Ba: PR đặt lịch (V3, tạo từ tuần trước) merge, staging migrate lại:\n$ ls mig; flyway migrate (staging)\nV1__tai_khoan.sql V2__lab_thiet_bi.sql V3__dat_lich.sql V4__ngay_nghi.sql \nflyway LỖI: Validate failed: Migrations have failed validation\nDetected resolved migration not applied to database: 3.\nTo ignore this migration, set -ignoreMigrationPatterns='*:ignored'. To allow executing this migration, set -outOfOrder=true.\nNeed more flexibility with validation rules? Learn more: https://help.red-gate.com/help/flyway-cli12/help_4.aspx?topic=flyway-blog/older-posts/customize-validation-rules-with-ignoremigrationpatterns\n(exit 1)\n### Thứ Tư: staging đã có V3 + V4 (bật outOfOrder để qua). Ai đó git revert PR ngày nghỉ ⇒ tệp V4 biến mất:\n$ ls mig; flyway migrate (staging)\nV1__tai_khoan.sql V2__lab_thiet_bi.sql V3__dat_lich.sql \nflyway: áp 0 migration, CSDL đang ở phiên bản 4\n(exit 0)\n$ psql staging -c '\\dt'\n public | dat_lich              | table | postgres\n public | flyway_schema_history | table | postgres\n public | lab                   | table | postgres\n public | ngay_nghi             | table | postgres\n public | nguoi_dung            | table | postgres\n public | thiet_bi              | table | postgres\n(6 rows)",
 "readmeLanDau": "$ node chay-readme.mjs mau/labflow readme/README-v2.md\nREADME-v2.md: 5 khối lệnh bash\n\n[khối 1 · dòng 14] node --version\n  v22.23.5\n  ✓ exit 0 (0.1 s)\n\n[khối 2 · dòng 24] cp .env.example .env ⏎ npm install ⏎ npm run kiem-moi-truong\n  up to date, audited 1 package in 677ms\n  found 0 vulnerabilities\n  > kiem-moi-truong\n  > node scripts/kiem-moi-truong.mjs\n  ✓ Node 22.23.5 (cần ≥ 22)\n  ✓ .env tồn tại\n  ✓ .env có PORT\n  ✓ .env có API_URL\n  ✓ exit 0 (6.1 s)\n\n[khối 3 · dòng 32] npm test\n  > test\n  > node --test test/\n  TAP version 13\n  # node:internal/modules/cjs/loader:1433\n  #   throw err;\n  #   ^\n  # Error: Cannot find module '/lam/test'\n  ✗ exit 1 — người mới kẹt ở dòng 32 của README.\n\nKẾT QUẢ: README HỎNG ở khối 3/5.\n(exit 1)"
};
